App.boot({id:'farms',title:'Farm Management',noCtx:true,render(el){const {money,num,esc,icon,formGrid}=U,S=Store,db=S.db;
 const act=db.farms.filter(f=>!f.archived);
 el.innerHTML=`<div class="page-head"><div><p>Add new farms, record acreage and archive farms no longer in use.</p></div><button class="btn" id="add">${icon('plus')} Add farm</button></div>
 <div class="grid g4"><div class="card kpi"><div class="ic">${icon('farm')}</div><div><div class="lbl">Active farms</div><div class="val">${act.length}</div></div></div><div class="card kpi gold"><div class="ic">${icon('archive')}</div><div><div class="lbl">Archived</div><div class="val">${db.farms.length-act.length}</div></div></div><div class="card kpi blue"><div class="ic">${icon('chart')}</div><div><div class="lbl">Total acres</div><div class="val">${num(act.reduce((s,f)=>s+Number(f.acres),0))}</div></div></div><div class="card kpi"><div class="ic">${icon('hari')}</div><div><div class="lbl">Hari acres</div><div class="val">${num(act.reduce((s,f)=>s+Number(f.acres)-Number(f.seri),0))}</div></div></div></div>
 <div class="card" style="margin-top:16px"><div class="card-head"><div><h3>All farms</h3><p>Hari acres = Total acres minus Seri acres. Archived farms remain in historical records but cannot be assigned to new employees.</p></div></div><div id="t"></div></div>`;
 U.dataTable(document.getElementById('t'),{rows:db.farms.map((f,i)=>({...f,i})),filters:[{label:'Status',options:['Active','Archived'],get:f=>f.archived?'Archived':'Active'}],columns:[
  {label:'Farm',value:f=>f.name,html:f=>`<b>${esc(f.name)}</b><br><small>${esc(f.location||'—')}${f.purchase?' • Purchased '+esc(f.purchase):''}</small>`},
  {label:'Total acres',num:1,value:f=>Number(f.acres),html:f=>Number(f.acres)?num(f.acres):'—'},{label:'Seri',num:1,value:f=>Number(f.seri),html:f=>Number(f.seri)?num(f.seri):'—'},
  {label:'Hari',num:1,value:f=>f.acres-f.seri,html:f=>Number(f.acres)?(Number(f.acres)-Number(f.seri)).toFixed(2):'—'},
  {label:'Staff',num:1,value:f=>db.users.filter(u=>u.active&&u.farm===f.name).length},
  {label:'Status',value:f=>f.archived?'Archived':'Active',html:f=>f.archived?'<span class="badge">Archived</span>':'<span class="badge ok">Active</span>'},
  {label:'Actions',sort:false,html:f=>`<button class="btn secondary sm" data-edit="${f.i}">${icon('edit')} Acreage</button> <button class="btn ${f.archived?'secondary':'ghost'} sm" data-arch="${f.i}">${icon('archive')} ${f.archived?'Restore':'Archive'}</button>`}]});
 const form=(f={})=>formGrid([{name:'name',label:'Farm name',value:f.name,attrs:`maxlength="80" ${f.name?'readonly':''}`,placeholder:'e.g. New Farm'},{name:'location',label:'Location',required:false,value:f.location,attrs:'maxlength="120"',placeholder:'Village / district'},{name:'acres',label:'Total acres',type:'number',value:f.acres||'',attrs:'min="0.01" step="0.01"'},{name:'seri',label:'Seri acres (owner-managed)',type:'number',value:f.seri??0,attrs:'min="0" step="0.01"'},{name:'purchase',label:'Purchase date',type:'date',required:false,value:f.purchase}])+'<p class="hint">Hari acres are calculated automatically (Total − Seri).</p>';
 const check=d=>{const acres=Number(d.acres),seri=Number(d.seri);if(!Number.isFinite(acres)||acres<=0||!Number.isFinite(seri)||seri<0||seri>acres)throw Error('Check acreage: Seri must be between zero and total acres.');return {acres,seri}};
 document.getElementById('add').onclick=()=>U.modal({title:'Add new farm',body:form(),submit:'Add farm',onSubmit:d=>{const name=d.name.trim();const {acres,seri}=check(d);if(!name)throw Error('Farm name required');if(db.farms.some(f=>f.name.toLowerCase()===name.toLowerCase()))throw Error('A farm with this name already exists.');
  db.farms.push({name,location:d.location.trim(),acres,seri,purchase:d.purchase,archived:false});S.log(`Added farm ${name}: ${acres} acres, Seri ${seri}, Hari ${(acres-seri).toFixed(2)}`);U.toast('New farm added successfully');App.refresh()}});
 U.on(el,'[data-edit]',b=>b.onclick=()=>{const f=db.farms[b.dataset.edit];U.modal({title:'Edit '+f.name,body:form(f),onSubmit:d=>{const {acres,seri}=check(d);Object.assign(f,{location:d.location.trim(),acres,seri,purchase:d.purchase});S.log(`Updated farm ${f.name}: ${acres} acres, Seri ${seri}`);U.toast('Farm updated');App.refresh()}})});
 U.on(el,'[data-arch]',b=>b.onclick=async()=>{const f=db.farms[b.dataset.arch];if(!f.archived&&db.users.some(u=>u.active&&u.farm===f.name))return U.toast('Disable or reassign active farm employees before archiving.','error');
  if(!await U.confirmBox(`${f.archived?'Restore':'Archive'} farm “${f.name}”?`,{ok:f.archived?'Restore':'Archive',danger:!f.archived}))return;f.archived=!f.archived;S.log(`${f.archived?'Archived':'Restored'} farm ${f.name}`);U.toast('Farm status updated');App.refresh()})}});
